import numpy as np

# Define the grid world
grid = [[0,2,5,9,"X",57,49,58,62],[1,4,8,12,"X",50,41,51,59],[3,7,11,14,"X",42,36,43,52],[6,10,13,15,17,"X",32,"X",56],["X","X","X",16,18,"X",27,"X",48],[63,60,53,"X",19,21,24,"X",40],[61,54,44,"X",20,23,26,31,35],[55,45,37,"X",22,"X",30,"X","X"],[46,38,33,28,25,29,34,39,47]]

# Define the goal state
goal = 47

# Function to calculate the Manhattan distance between two states
def manhattan_distance(state1, state2):
    x1, y1 = np.where(np.array(grid) == state1)
    x2, y2 = np.where(np.array(grid) == state2)
    return abs(x1[0] - x2[0]) + abs(y1[0] - y2[0])

# Calculate the distance from each state to the goal
distances = {}
for i in range(len(grid)):
    for j in range(len(grid[i])):
        if grid[i][j] != "X":
            distances[grid[i][j]] = manhattan_distance(grid[i][j], goal)

# Group states into abstract states based on their distance to the goal
abstract_states = {}
for state, distance in distances.items():
    if distance not in abstract_states:
        abstract_states[distance] = [state]
    else:
        abstract_states[distance].append(state)

print(abstract_states)
